parameters.functionCode:
const body = $input.first().json.body;

const bedrag = parseFloat(body.bedrag || 0);
const btwPct = parseFloat(body.btw || 21);

const btwBedrag = Math.round(bedrag * btwPct / 100 * 100) / 100;
const totaal = Math.round((bedrag + btwBedrag) * 100) / 100;

// Grootboekcode extraheren (bijv. '4400 Inkoopkosten' → '4400')
const grootboekRaw = body.grootboek || '4400 Inkoopkosten';
const grootboekCode = grootboekRaw.split(' ')[0];

// Datum: gebruik opgegeven datum of vandaag
const datum = body.datum || new Date().toISOString().split('T')[0];

return [{
  json: {
    leverancier: body.leverancier || '',
    omschrijving: body.omschrijving || '',
    bedrag,
    btw_percentage: btwPct,
    btw_bedrag: btwBedrag,
    totaal,
    grootboek_code: grootboekCode,
    datum
  }
}];

